INSERT INTO `syllabus` (`province`,`year`,`subject`,`source_title`,`scope_json`,`references_json`,`designated_works_json`)
VALUES ('山东', 2025, '英语', '山东省2025年普通高等教育专科升本科招生考试要求',
  '{"blocks":[{"heading":"I. 考试内容与要求","paragraphs":["依据《高等职业教育专科英语课程标准（2021年版）》，考查语言知识与语言运用能力。"],"items":[],"children":[{"heading":"一、语言知识","paragraphs":[],"items":[],"children":[{"heading":"（一）词汇","paragraphs":["认知约 3000 个英语单词及常用词组（见课程标准附录词汇表），能按基本构词法识别生词，并在语篇中理解与运用词汇。"],"items":[],"children":[],"highlight":false},{"heading":"（二）语法","paragraphs":["掌握基本英语语法规则，能在语篇中正确运用所学语法知识。"],"items":[],"children":[],"highlight":false}],"highlight":false},{"heading":"二、语言运用","paragraphs":[],"items":[],"children":[{"heading":"（一）阅读","paragraphs":["能读懂书报杂志中难度中等的一般性话题短文及信函、说明书、合同等实用文字。考生应能："],"items":["理解文中具体信息","根据上下文判断指代关系","根据上下文和构词法推断词义","理解文章主旨要义","理解作者意图、观点或态度","理解文章基本结构与逻辑关系","根据文章内容进行判断与推理","快速查找相关信息"],"children":[],"highlight":false},{"heading":"（二）翻译","paragraphs":["能就日常生活与职场相关话题进行英汉互译。考生应能："],"items":["正确理解原文","运用基本翻译技巧","用通顺得体的语言准确传达原意"],"children":[],"highlight":false},{"heading":"（三）写作","paragraphs":["掌握一定语用知识，能按要求完成简单书面表达。考生应能："],"items":["撰写常见主题应用文","描述人物或事件并加以评论","根据文字提纲或图表数据写短文或报告","表达清楚连贯，语法正确，结构完整，格式规范"],"children":[],"highlight":false}],"highlight":false}],"highlight":false},{"heading":"II. 考试形式与题型范围","paragraphs":[],"items":[],"children":[{"heading":"一、考试形式","paragraphs":["闭卷、笔试。试卷满分 100 分，考试时间 120 分钟。"],"items":[],"children":[],"highlight":false},{"heading":"二、题型范围","paragraphs":[],"items":["单项选择题","多项选择题","填空题","阅读理解","英译汉","汉译英","写作"],"children":[],"highlight":false}],"highlight":false}]}',
  '[{"title":"高等职业教育专科英语课程标准（2021年版）","editors":"中华人民共和国教育部制定","edition":null,"publisher":"高等教育出版社","publishedAt":"2021年","note":null}]',
  NULL);

INSERT INTO `syllabus` (`province`,`year`,`subject`,`source_title`,`scope_json`,`references_json`,`designated_works_json`)
VALUES ('山东', 2025, '政治', '山东省2025年普通高等教育专科升本科招生考试要求',
  '{"blocks":[{"heading":"I. 考试内容与要求","paragraphs":["考试内容包括：思想道德与法治；毛泽东思想和中国特色社会主义理论体系概论；习近平新时代中国特色社会主义思想概论；党的二十大和二十届历次全会精神；时事政治。考查识记、理解、应用能力。"],"items":[],"children":[{"heading":"一、思想道德与法治","paragraphs":[],"items":["领悟人生真谛 把握人生方向","追求远大理想 坚定崇高信念","继承优良传统 弘扬中国精神","明确价值要求 践行价值准则","遵守道德规范 锤炼道德品格","学习法治思想 提升法治素养"],"children":[],"highlight":false},{"heading":"二、毛泽东思想和中国特色社会主义理论体系概论","paragraphs":[],"items":["毛泽东思想及其历史地位","新民主主义革命理论","社会主义改造理论","社会主义建设道路初步探索的理论成果","中国特色社会主义理论体系的形成发展","邓小平理论","“三个代表”重要思想","科学发展观"],"children":[],"highlight":false},{"heading":"三、习近平新时代中国特色社会主义思想概论","paragraphs":[],"items":[],"children":[{"heading":"（1）新时代坚持和发展中国特色社会主义","paragraphs":[],"items":[],"children":[],"highlight":false},{"heading":"（2）以中国式现代化全面推进中华民族伟大复兴","paragraphs":[],"items":[],"children":[],"highlight":false},{"heading":"（3）坚持党的全面领导","paragraphs":[],"items":[],"children":[],"highlight":false},{"heading":"（4）坚持以人民为中心","paragraphs":[],"items":[],"children":[],"highlight":false},{"heading":"（5）全面深化改革开放","paragraphs":[],"items":[],"children":[],"highlight":false},{"heading":"（6）推动高质量发展","paragraphs":[],"items":[],"children":[],"highlight":false},{"heading":"（7）社会主义现代化建设的教育、科技、人才战略","paragraphs":[],"items":[],"children":[],"highlight":false},{"heading":"（8）发展全过程人民民主","paragraphs":[],"items":[],"children":[],"highlight":false},{"heading":"（9）全面依法治国","paragraphs":[],"items":[],"children":[],"highlight":false},{"heading":"（10）建设社会主义文化强国","paragraphs":[],"items":[],"children":[],"highlight":false},{"heading":"（11）以保障和改善民生为重点加强社会建设","paragraphs":[],"items":[],"children":[],"highlight":false},{"heading":"（12）建设社会主义生态文明","paragraphs":[],"items":[],"children":[],"highlight":false},{"heading":"（13）维护和塑造国家安全","paragraphs":[],"items":[],"children":[],"highlight":false},{"heading":"（14）建设巩固国防和强大人民军队","paragraphs":[],"items":[],"children":[],"highlight":false},{"heading":"（15）坚持“一国两制”和推进祖国完全统一","paragraphs":[],"items":[],"children":[],"highlight":false},{"heading":"（16）中国特色大国外交和推动构建人类命运共同体","paragraphs":[],"items":[],"children":[],"highlight":false},{"heading":"（17）全面从严治党","paragraphs":[],"items":[],"children":[],"highlight":false}],"highlight":false},{"heading":"四、党的二十大和二十届历次全会精神","paragraphs":["掌握党的二十大及二十届历次全会主要精神与重大部署。"],"items":[],"children":[],"highlight":false},{"heading":"五、时事政治","paragraphs":["2024年3月1日至2025年2月28日国内外重大时事，以及中国共产党和中国政府此阶段重大路线、方针、政策。"],"items":[],"children":[],"highlight":true}],"highlight":false},{"heading":"II. 考试形式与题型范围","paragraphs":[],"items":[],"children":[{"heading":"一、考试形式","paragraphs":["闭卷、笔试。试卷满分 100 分，考试时间 120 分钟。"],"items":[],"children":[],"highlight":false},{"heading":"二、题型范围","paragraphs":[],"items":["单项选择题","多项选择题","判断题","简答题","论述题","辨析题","材料分析题"],"children":[],"highlight":false}],"highlight":false}]}',
  '[{"title":"思想道德与法治","editors":null,"edition":"2023年版","publisher":"高等教育出版社","publishedAt":null,"note":"马克思主义理论研究和建设工程重点教材"},{"title":"毛泽东思想和中国特色社会主义理论体系概论","editors":null,"edition":"2023年版","publisher":"高等教育出版社","publishedAt":null,"note":"马克思主义理论研究和建设工程重点教材"},{"title":"习近平新时代中国特色社会主义思想概论","editors":null,"edition":null,"publisher":"高等教育出版社、人民出版社","publishedAt":"2023年","note":"马克思主义理论研究和建设工程重点教材"}]',
