INSERT INTO `syllabus` (`province`,`year`,`subject`,`source_title`,`scope_json`,`references_json`,`designated_works_json`)
VALUES ('山东', 2025, '计算机', '山东省2025年普通高等教育专科升本科招生考试要求',
  '{"blocks":[{"heading":"I. 考试内容与要求","paragraphs":["依据高等职业教育专科信息技术课程标准（2021年版），考查信息素养、计算思维与计算机应用能力。软件环境：Windows 10、Word/Excel/PowerPoint 2016（2026 年考纲仍沿用该版本）。"],"items":[],"children":[{"heading":"一、信息与计算机基础知识","paragraphs":[],"items":["信息、数据、信息技术与信息社会","计算机概念、发展、类型、应用与趋势；国产计算机概况","进制转换；数值、字符、图像等表示与存储单位","计算机系统组成、体系结构、软硬件；微型机性能指标与常见设备","多媒体技术概念、元素、处理与系统组成"],"children":[],"highlight":false},{"heading":"二、计算思维","paragraphs":[],"items":["计算思维概念及其在社会生活中的应用","计算机求解问题的基本方法","算法基础知识、典型策略与复杂度；时/空优化思路","程序基本结构与流程表达；面向对象程序设计思想"],"children":[],"highlight":false},{"heading":"三、操作系统","paragraphs":[],"items":["操作系统概念、功能、特征与分类；麒麟、统信、鸿蒙等国产系统","Windows 10 桌面、窗口、对话框、剪贴板、任务管理器等操作","文件与文件夹管理","系统设置；画图、截图、录音机等附件应用"],"children":[],"highlight":false},{"heading":"四、文档处理","paragraphs":[],"items":["常见文档格式与处理软件；WPS Office 特点","Word 2016 编辑、查找替换、多窗口等基本操作","字符/段落格式、分节分页分栏、页眉页脚、样式模板、页面设置","表格创建编辑与计算；图文混排（图片、形状、SmartArt、公式等）","文档保护与打印、邮件合并、引用与审阅；协同编辑"],"children":[],"highlight":false},{"heading":"五、电子表格处理","paragraphs":[],"items":["Excel 2016 工作簿/工作表/单元格与数据清单","工作表与行列管理；数据输入、填充与批注","相对/绝对/三维引用；公式与常用函数","格式化、条件格式；排序筛选分类汇总、透视表、模拟分析","图表与迷你图；页面布局与打印"],"children":[],"highlight":false},{"heading":"六、演示文稿制作","paragraphs":[],"items":["PowerPoint 2016 视图与外观修饰","幻灯片内容编辑与 SmartArt","动画、超链接与动作；切换与放映设置","打印、共享、导出与选项设置"],"children":[],"highlight":false},{"heading":"七、数据库技术","paragraphs":[],"items":["数据库与关系数据库基本概念、数据模型与关系运算","表操作与 SQL 基本语句；库设计方法概要","NoSQL（键值、列族、文档、图）基本概念与应用"],"children":[],"highlight":false},{"heading":"八、计算机网络与信息检索","paragraphs":[],"items":["网络概念、组成、分类、性能与体系结构","Internet 接入、IP 与域名、WWW、浏览器与电子邮件","FTP、Telnet、即时通信与音视频/文档下载","网站网页、Web 服务器、HTML 基础","信息检索流程；搜索引擎与布尔等检索方法；专用资源平台检索"],"children":[],"highlight":false},{"heading":"九、信息安全与社会责任","paragraphs":[],"items":["信息安全基础知识","密码、防火墙、杀毒等常见安全技术","网络礼仪与信息伦理；隐私保护与虚假信息识别","相关法律法规与职业自律；自主可控与国产安全产品"],"children":[],"highlight":false},{"heading":"十、新一代信息技术","paragraphs":[],"items":["云计算、大数据、物联网、移动通信、人工智能、区块链、量子信息、元宇宙等概念与代表技术","主要技术特征","在数字经济、智能制造、智慧城市等领域的应用与社会影响","各类新技术之间的关系"],"children":[],"highlight":false}],"highlight":false},{"heading":"II. 考试形式与题型范围","paragraphs":[],"items":[],"children":[{"heading":"一、考试形式","paragraphs":["闭卷、笔试。试卷满分 100 分，考试时间 120 分钟。"],"items":[],"children":[],"highlight":false},{"heading":"二、题型范围","paragraphs":[],"items":["单项选择题","多项选择题","判断题","填空题","简答题","分析题","操作题","综合应用题"],"children":[],"highlight":false}],"highlight":false}]}',
  '[]',
  NULL);

INSERT INTO `syllabus` (`province`,`year`,`subject`,`source_title`,`scope_json`,`references_json`,`designated_works_json`)
VALUES ('山东', 2025, '大学语文', '山东省2025年普通高等教育专科升本科招生考试要求',
  '{"blocks":[{"heading":"I. 考试内容与要求","paragraphs":["考查文学文化常识、汉语基础知识、作品阅读分析与写作；能力层次包括识记、理解、综合分析、表达应用、鉴赏评价与探究。"],"items":[],"children":[{"heading":"一、文学文化常识","paragraphs":[],"items":["掌握中外重要作家作品基本知识（姓名字号、时代、代表作与文集、文学主张与成就等）及重要典籍的成书、内容、特征与文学史地位","识记古代诗文名句","掌握古今各类文体知识","掌握中外文学史上重要流派与现象","掌握中国传统文化基本常识"],"children":[],"highlight":false},{"heading":"二、汉语基础知识","paragraphs":[],"items":["理解文言以单音词为主的特点；掌握常用文言实词；识别通假字、古今字","掌握虚词：之、其、于、以、而、则、乃、者、所、焉、且 在不同语境中的意义与用法","分析词类活用、使动、意动、名词作状语及判断句、被动句、宾语前置等，并能准确翻译","掌握比喻、比拟、借代、双关、对偶等常见修辞手法"],"children":[],"highlight":false},{"heading":"三、作品阅读分析","paragraphs":[],"items":["了解作者生平、时代背景与作品反映的社会生活","理解并分析体裁特征、主要表现手法与写作特点","鉴赏文学形象，品味语言，理解重要语句含义","把握并概括作品主题与思想意义"],"children":[],"highlight":false},{"heading":"四、写作","paragraphs":[],"items":[],"children":[{"heading":"（一）应用写作","paragraphs":["根据材料或情境选择恰当文体。含通知、通报、请示、函等公文，以及声明、启事、证明、请柬、借条、收条、请假条、介绍信、求职信、新闻稿等事务文书。要求主题明确、信息完整、结构齐全、格式规范、表达得体。"],"items":[],"children":[],"highlight":false},{"heading":"（二）文学写作","paragraphs":["主要考查议论文、记叙文写作。要求思想积极、符合文体、内容充实、主题鲜明、层次清楚、结构完整、语言通顺、标点正确、书写工整；字数不少于 800 字。"],"items":[],"children":[],"highlight":false}],"highlight":false}],"highlight":false},{"heading":"II. 考试形式与题型范围","paragraphs":[],"items":[],"children":[{"heading":"一、考试形式","paragraphs":["闭卷、笔试。试卷满分 100 分，考试时间 120 分钟。"],"items":[],"children":[],"highlight":false},{"heading":"二、题型范围","paragraphs":[],"items":["单项选择题","多项选择题","填空题","判断题","词语解释题","文言文翻译题","阅读分析题","写作题"],"children":[],"highlight":false}],"highlight":false}]}',
  '[]',
  '[{"seq":1,"title":"《郑伯克段于鄢》","authorOrSource":"《左传》"},{"seq":2,"title":"《齐桓公伐楚》","authorOrSource":"《左传》"},{"seq":3,"title":"《烛之武退秦师》","authorOrSource":"《左传》"},{"seq":4,"title":"《吕相绝秦》","authorOrSource":"《左传》"},{"seq":5,"title":"《勾践灭吴》","authorOrSource":"《国语》"},{"seq":6,"title":"《邹忌讽齐王纳谏》","authorOrSource":"《战国策》"},{"seq":7,"title":"《触龙说赵太后》","authorOrSource":"《战国策》"},{"seq":8,"title":"《子路曾皙冉有公西华侍坐》","authorOrSource":"《论语》"},{"seq":9,"title":"《季氏将伐颛臾》","authorOrSource":"《论语》"},{"seq":10,"title":"《逍遥游》（“北冥有鱼”至“圣人无名”）","authorOrSource":"《庄子》"},{"seq":11,"title":"《秋水》（“秋水时至”至“不似尔向之自多于水平”）","authorOrSource":"《庄子》"},{"seq":12,"title":"《齐桓晋文之事》","authorOrSource":"《孟子》"},{"seq":13,"title":"《许行》（“有为神农之言”至“而暇耕乎”）","authorOrSource":"《孟子》"},{"seq":14,"title":"《劝学》（“君子曰学不可以已”至“故君子结于一也”）","authorOrSource":"《荀子》"},{"seq":15,"title":"《谏逐客书》","authorOrSource":"秦·李斯"},{"seq":16,"title":"《论贵粟疏》","authorOrSource":"汉·晁错"},{"seq":17,"title":"《鸿门宴》","authorOrSource":"汉·司马迁《史记》"},{"seq":18,"title":"《报任安书》","authorOrSource":"汉·司马迁"},{"seq":19,"title":"《巫山巫峡》","authorOrSource":"魏·郦道元《水经注》"},{"seq":20,"title":"《张中丞传后叙》","authorOrSource":"唐·韩愈"},{"seq":21,"title":"《钴鉧潭西小丘记》","authorOrSource":"唐·柳宗元"},{"seq":22,"title":"《六国论》","authorOrSource":"宋·苏洵"},{"seq":23,"title":"《留侯论》","authorOrSource":"宋·苏轼"},{"seq":24,"title":"《传是楼记》","authorOrSource":"清·汪琬"},{"seq":25,"title":"《小翠》","authorOrSource":"清·蒲松龄《聊斋志异》"}]');

INSERT INTO `syllabus` (`province`,`year`,`subject`,`source_title`,`scope_json`,`references_json`,`designated_works_json`)
VALUES ('山东', 2025, '高等数学I', '山东省2025年普通高等教育专科升本科招生考试要求',
  '{"blocks":[{"heading":"I. 考试内容与要求","paragraphs":["掌握高等数学基本概念、基本理论与基本方法，考查识记、理解、计算、推理与应用能力。"],"items":[],"children":[{"heading":"一、函数、极限与连续","paragraphs":[],"items":[],"children":[{"heading":"（一）函数","paragraphs":[],"items":["理解函数概念；求定义域、表达式与函数值；建立应用问题函数关系","掌握有界性、单调性、周期性与奇偶性","理解分段函数、反函数与复合函数","掌握四则运算与复合运算","掌握基本初等函数性质与图形；理解初等函数概念"],"children":[],"highlight":false},{"heading":"（二）极限","paragraphs":[],"items":["理解数列极限与函数极限（含左右极限）及存在关系","理解极限性质与收敛准则；熟练掌握运算法则","熟练掌握两个重要极限并用于求极限","理解无穷小与无穷大；比较与等价无穷小求极限"],"children":[],"highlight":false},{"heading":"（三）连续","paragraphs":[],"items":["理解连续性（含左右连续）与间断点类型","掌握连续函数运算；初等函数在定义区间连续","利用连续性求极限","掌握闭区间连续函数性质并应用","会求水平与铅直渐近线"],"children":[],"highlight":false}],"highlight":false},{"heading":"二、一元函数微分学","paragraphs":[],"items":[],"children":[{"heading":"（一）导数与微分","paragraphs":[],"items":["理解导数概念与几何意义；用定义求导；切线法线方程；可导与连续关系","熟练掌握四则与复合求导及基本初等函数导数公式","掌握隐函数、对数求导与参数方程求导；分段函数导数","理解高阶导数并会求","理解微分概念与运算法则；求一阶微分"],"children":[],"highlight":false},{"heading":"（二）中值定理及导数的应用","paragraphs":[],"items":["理解罗尔定理、拉格朗日中值定理并应用","熟练掌握洛必达法则求各类未定式极限","理解驻点、极值点及其关系；求最值并应用","用导数判断单调性、证明不等式","理解凹凸性与拐点"],"children":[],"highlight":false}],"highlight":false},{"heading":"三、一元函数积分学","paragraphs":[],"items":[],"children":[{"heading":"（一）不定积分","paragraphs":[],"items":["理解原函数与不定积分；存在定理与性质","熟练掌握基本积分公式","熟练掌握换元法与分部积分法","掌握简单有理函数不定积分"],"children":[],"highlight":false},{"heading":"（二）定积分","paragraphs":[],"items":["理解定积分概念、几何意义与可积条件","掌握性质与应用","理解变上限积分；求其导数；熟练掌握牛顿-莱布尼茨公式","熟练掌握定积分换元与分部积分","用定积分求平面图形面积与旋转体体积","理解广义积分概念"],"children":[],"highlight":false}],"highlight":false},{"heading":"四、向量代数与空间解析几何","paragraphs":[],"items":[],"children":[{"heading":"（一）向量代数","paragraphs":[],"items":["理解空间直角坐标系与向量；求单位向量、方向余弦与投影","掌握向量线性运算、点积与叉积","求夹角；掌握平行与垂直条件"],"children":[],"highlight":false},{"heading":"（二）平面与直线","paragraphs":[],"items":["求平面点法式、一般式；判断两平面位置关系","求点到平面距离","求直线对称式、一般式、参数式；判断两直线位置关系","判断直线与平面位置关系"],"children":[],"highlight":false}],"highlight":false},{"heading":"五、多元函数微积分学","paragraphs":[],"items":[],"children":[{"heading":"（一）多元函数微分学","paragraphs":[],"items":["理解多元函数；二元函数极限与连续；求定义域","理解偏导数、可微与全微分；求一阶、二阶偏导数与全微分","掌握复合函数偏导数","由 F(x,y,z)=0 确定隐函数的一阶偏导数","理解驻点与极值；求二元函数极值"],"children":[],"highlight":false},{"heading":"（二）二重积分","paragraphs":[],"items":["理解二重积分概念、性质与几何意义","掌握直角坐标与极坐标下的计算","理解累次积分并会交换积分次序"],"children":[],"highlight":false}],"highlight":false},{"heading":"六、无穷级数","paragraphs":[],"items":[],"children":[{"heading":"（一）数项级数","paragraphs":[],"items":["理解收敛发散；掌握基本性质与必要条件","掌握几何级数、调和级数与 p 级数敛散性","掌握正项级数比较判别法与比值判别法","掌握交错级数莱布尼茨判别法","理解绝对收敛与条件收敛"],"children":[],"highlight":false},{"heading":"（二）幂级数","paragraphs":[],"items":["理解幂级数；求收敛半径、区间与收敛域","掌握收敛区间内的和差、逐项求导与积分性质","掌握和函数在收敛域上的性质","利用逐项求导积分求和函数","熟记常见麦克劳林级数；展开简单初等函数"],"children":[],"highlight":false}],"highlight":false},{"heading":"七、常微分方程","paragraphs":[],"items":[],"children":[{"heading":"（一）一阶微分方程","paragraphs":[],"items":["理解微分方程阶、解、通解、初值与特解","掌握可分离变量方程","掌握一阶线性微分方程"],"children":[],"highlight":false},{"heading":"（二）二阶线性微分方程","paragraphs":[],"items":["理解二阶线性方程解的结构","掌握二阶常系数齐次线性微分方程"],"children":[],"highlight":false}],"highlight":false}],"highlight":false},{"heading":"II. 考试形式与题型范围","paragraphs":[],"items":[],"children":[{"heading":"一、考试形式","paragraphs":["闭卷、笔试。试卷满分 100 分，考试时间 120 分钟。"],"items":[],"children":[],"highlight":false},{"heading":"二、题型范围","paragraphs":[],"items":["选择题","填空题","判断题","计算题","解答题","证明题","应用题"],"children":[],"highlight":false}],"highlight":false}]}',
  '[]',
  NULL);

